import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

def extract_document_structure(document_path):
    textract_client = boto3.client('textract')

    try:
        with open(document_path, 'rb') as document:
            response = textract_client.analyze_document(
                Document={'Bytes': document.read()},
                FeatureTypes=['TABLES']
            )

        tables = []
        for block in response['Blocks']:
            if block['BlockType'] == 'TABLE':
                table = {
                    'cells': [],
                    'rows': []
                }
                for relationship in block['Relationships']:
                    if relationship['Type'] == 'CHILD':
                        for child_id in relationship['Ids']:
                            child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                            if child_block['BlockType'] == 'CELL':
                                table['cells'].append({
                                    'text': child_block.get('Text', ''),
                                    'row_index': child_block['RowIndex'],
                                    'column_index': child_block['ColumnIndex']
                                })
                            elif child_block['BlockType'] == 'ROW':
                                table['rows'].append({
                                    'row_index': child_block['RowIndex']
                                })
                tables.append(table)

        return tables

    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f"AWS credentials error: {e}")
        return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None
